"use client";

import { useEffect, useId, useLayoutEffect, useRef, useState, type CSSProperties, type KeyboardEvent } from "react";

/*
 * World Map Continental – a world map illustration with one highlighted continent, in a single self-contained file.
 * Every continent is one merged shape without country borders: the highlighted one sits white with a soft
 * shadow on a solid light gray world, and a soft pastel band travels along its coastline.
 * A small menu in the top-left corner switches the continent; the old highlight fades out while the new
 * one settles in. Equal Earth projection of Natural Earth 1:110m shapes (public domain), Antarctica cropped.
 */

export type Continent = "north-america" | "south-america" | "europe" | "africa" | "asia" | "oceania";

export type WorldMapProps = {
  /** Highlighted continent (controlled) */
  continent?: Continent;
  /** Continent highlighted first when `continent` is not set */
  defaultContinent?: Continent;
  /** Called when the viewer picks a continent in the menu */
  onContinentChange?: (continent: Continent) => void;
  /** Show the continent menu in the top-left corner */
  showSwitcher?: boolean;
  className?: string;
  /** Accessible description of the map; a function receives the current continent */
  label?: string | ((continent: Continent) => string);
};

const OPTIONS: { value: Continent; name: string }[] = [
  { value: "north-america", name: "North America" },
  { value: "south-america", name: "South America" },
  { value: "europe", name: "Europe" },
  { value: "africa", name: "Africa" },
  { value: "asia", name: "Asia" },
  { value: "oceania", name: "Oceania" },
];

type Phase = "idle" | "enter" | "exit";

export function WorldMap({
  continent,
  defaultContinent = "europe",
  onContinentChange,
  showSwitcher = true,
  className,
  label,
}: WorldMapProps) {
  const id = "ui-wm" + useId().replace(/[^a-zA-Z0-9_-]/g, "");
  const root = useRef<HTMLDivElement>(null);
  const [own, setOwn] = useState<Continent>(defaultContinent);
  const current = continent ?? own;
  const option = OPTIONS.find((o) => o.value === current) ?? OPTIONS[2];

  const select = (next: Continent) => {
    if (continent === undefined) setOwn(next);
    if (next !== current) onContinentChange?.(next);
  };

  // The current highlight plus any highlight that is still fading out
  const [layers, setLayers] = useState<{ key: number; continent: Continent; phase: Phase }[]>([
    { key: 0, continent: current, phase: "idle" },
  ]);
  useEffect(() => {
    setLayers((all) => {
      const top = all[all.length - 1];
      if (top.continent === current) return all;
      return [
        ...all.map((l) => ({ ...l, phase: "exit" as Phase })),
        { key: top.key + 1, continent: current, phase: "enter" as Phase },
      ];
    });
  }, [current]);
  useEffect(() => {
    if (!layers.some((l) => l.phase === "exit")) return;
    const timer = setTimeout(() => setLayers((all) => all.filter((l) => l.phase !== "exit")), 480);
    return () => clearTimeout(timer);
  }, [layers]);

  // The menu scales with the illustration, so it still fits in small previews
  const [scale, setScale] = useState(1);
  useEffect(() => {
    const el = root.current;
    if (!el) return;
    // The world is wide and flat, so the height of the open list counts as well
    const fit = () => setScale(Math.min(1, Math.max(0.62, Math.min(el.clientWidth / 540, el.clientHeight / 260))));
    fit();
    const observer = new ResizeObserver(fit);
    observer.observe(el);
    return () => observer.disconnect();
  }, []);

  return (
    <div
      ref={root}
      className={["ui-wm", className].filter(Boolean).join(" ")}
      style={{ "--ui-wm-s": scale } as CSSProperties}
    >
      {/* React 19 hoists this into <head> once, no matter how many instances render */}
      <style href="ui-world-map" precedence="default">
        {css}
      </style>
      <div
        className="ui-wm-map"
        role="img"
        aria-label={
          typeof label === "function" ? label(current) : (label ?? `World map with ${option.name} highlighted`)
        }
      >
        <svg className="ui-wm-art" viewBox="0 0 540 242" aria-hidden="true">
          <defs>
            <filter id={`${id}-shadow`} x="-15%" y="-15%" width="130%" height="130%">
              <feDropShadow className="ui-wm-drop" dx="0" dy="2" stdDeviation="2.5" floodColor="#1F2128" floodOpacity="0.1" />
            </filter>
            {/* Colors of the band that travels along the coastline */}
            <linearGradient id={`${id}-shine`} gradientUnits="userSpaceOnUse" x1="0" y1="0" x2="540" y2="242">
              <stop offset="0%" stopColor="#FFA0AB" />
              <stop offset="33%" stopColor="#FFB89E" />
              <stop offset="66%" stopColor="#C8A8E5" />
              <stop offset="100%" stopColor="#A8B5FF" />
            </linearGradient>
            <filter id={`${id}-blur`} x="-20%" y="-20%" width="140%" height="140%">
              <feGaussianBlur stdDeviation="4" />
            </filter>
          </defs>

          {/* The whole world in one solid light gray; the stroke in the fill color closes the seam between Europe and Asia */}
          <g className="ui-wm-land" fill="#E8E8E8" stroke="#E8E8E8" strokeWidth="0.5" strokeLinejoin="round">
            {OPTIONS.map((o) => (
              <path key={o.value} d={LAND[o.value]} />
            ))}
          </g>

          {layers.map((l) => (
            <Highlight key={l.key} id={`${id}-${l.key}`} shared={id} continent={l.continent} phase={l.phase} />
          ))}
        </svg>
      </div>
      {showSwitcher && <Switcher value={current} onChange={select} />}
    </div>
  );
}

/* ---------- The highlighted continent: white shape, soft shadow and the travelling band ---------- */

function Highlight({ id, shared, continent, phase }: { id: string; shared: string; continent: Continent; phase: Phase }) {
  const land = LAND[continent];
  // The main landmass is the first shape of each continent's path; the band travels around it
  const coast = land.slice(0, land.indexOf("z") + 1);
  const [ox, oy] = CENTER[continent];
  return (
    <g className="ui-wm-layer" data-phase={phase} style={{ transformOrigin: `${ox}px ${oy}px` }}>
      <defs>
        {/* Hides the glow on the land, so it only spreads outwards from the coastline */}
        <mask id={`${id}-outside`} maskUnits="userSpaceOnUse" x="0" y="0" width="540" height="242">
          <rect x="0" y="0" width="540" height="242" fill="#FFFFFF" />
          <path d={land} fill="#000000" />
        </mask>
      </defs>

      <path
        d={land}
        filter={`url(#${shared}-shadow)`}
        className="ui-wm-focus"
        fill="#FFFFFF"
        stroke="#E2E2E2"
        strokeWidth="0.5"
        strokeLinejoin="round"
      />

      {/* Band on the coastline: a blurred glow underneath, three sharp layers with shorter dashes on top */}
      <g fill="none" stroke={`url(#${shared}-shine)`} strokeLinecap="round" strokeLinejoin="round">
        <path
          className="ui-wm-band"
          d={coast}
          pathLength={1000}
          strokeWidth="6"
          strokeDasharray="180 820"
          filter={`url(#${shared}-blur)`}
          mask={`url(#${id}-outside)`}
          opacity="0.45"
        />
        <path className="ui-wm-band" d={coast} pathLength={1000} strokeWidth="1.4" strokeDasharray="200 800" opacity="0.32" />
        <path
          className="ui-wm-band ui-wm-band--1"
          d={coast}
          pathLength={1000}
          strokeWidth="1.4"
          strokeDasharray="140 860"
          strokeDashoffset="-30"
          opacity="0.55"
        />
        <path
          className="ui-wm-band ui-wm-band--2"
          d={coast}
          pathLength={1000}
          strokeWidth="1.4"
          strokeDasharray="80 920"
          strokeDashoffset="-60"
        />
      </g>
    </g>
  );
}

/* ---------- Continent menu: a pill that morphs open into a listbox ---------- */

function Switcher({ value, onChange }: { value: Continent; onChange: (continent: Continent) => void }) {
  const id = "ui-wm-menu" + useId().replace(/[^a-zA-Z0-9_-]/g, "");
  const trigger = useRef<HTMLButtonElement>(null);
  const panel = useRef<HTMLDivElement>(null);
  const rows = useRef<(HTMLDivElement | null)[]>([]);
  const [open, setOpen] = useState(false);
  const [active, setActive] = useState(0);
  const [from, setFrom] = useState({ w: 0, h: 0 });
  const [fill, setFill] = useState({ y: 0, h: 0, glide: false });
  // The fill only shows while the pointer is over a row (or the keyboard moves through the list)
  const [shown, setShown] = useState(false);
  const wasShown = useRef(false);
  const selected = Math.max(
    0,
    OPTIONS.findIndex((o) => o.value === value),
  );

  // The closed menu is a trigger-sized pill in its top-left corner; opening morphs it to the full panel
  useLayoutEffect(() => {
    const t = trigger.current;
    if (t) setFrom({ w: t.offsetWidth, h: t.offsetHeight });
  }, [value, open]);

  const show = () => {
    setActive(selected);
    setShown(false);
    setOpen(true);
  };
  const close = (refocus: boolean) => {
    setOpen(false);
    if (refocus) trigger.current?.focus();
  };
  const pick = (i: number) => {
    onChange(OPTIONS[i].value);
    close(true);
  };

  useEffect(() => {
    if (open) panel.current?.focus({ preventScroll: true });
  }, [open]);

  // One fill glides between rows; when it first appears it fades in on the spot
  useLayoutEffect(() => {
    const row = rows.current[active];
    if (row) setFill({ y: row.offsetTop, h: row.offsetHeight, glide: wasShown.current && shown });
    wasShown.current = shown;
  }, [active, open, shown]);

  // Click outside closes
  useEffect(() => {
    if (!open) return;
    const away = (event: PointerEvent) => {
      const target = event.target as Node;
      if (panel.current?.contains(target) || trigger.current?.contains(target)) return;
      close(false);
    };
    document.addEventListener("pointerdown", away);
    return () => document.removeEventListener("pointerdown", away);
  }, [open]);

  const onKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    const last = OPTIONS.length - 1;
    const moves: Record<string, number> = {
      ArrowDown: Math.min(last, active + 1),
      ArrowUp: Math.max(0, active - 1),
      Home: 0,
      End: last,
    };
    if (event.key in moves) {
      event.preventDefault();
      setActive(moves[event.key]);
      setShown(true);
    } else if (event.key === "Enter" || event.key === " ") {
      event.preventDefault();
      pick(active);
    } else if (event.key === "Escape") {
      event.preventDefault();
      event.stopPropagation();
      close(true);
    } else if (event.key === "Tab") {
      close(false);
    }
  };

  return (
    <div className="ui-wm-switch">
      <button
        ref={trigger}
        type="button"
        className="ui-wm-trigger"
        aria-haspopup="listbox"
        aria-expanded={open}
        aria-controls={`${id}-list`}
        aria-label={`Continent: ${OPTIONS[selected].name}`}
        onClick={() => (open ? close(false) : show())}
        onKeyDown={(event) => {
          if (event.key === "ArrowDown" || event.key === "ArrowUp") {
            event.preventDefault();
            show();
          }
        }}
      >
        <span>{OPTIONS[selected].name}</span>
        <ChevronIcon />
      </button>
      <div
        className="ui-wm-menu"
        data-open={open}
        style={{ "--from-w": `${from.w}px`, "--from-h": `${from.h}px` } as CSSProperties}
        inert={!open}
      >
        <div
          ref={panel}
          id={`${id}-list`}
          className="ui-wm-panel"
          role="listbox"
          tabIndex={-1}
          aria-label="Select a continent"
          aria-activedescendant={`${id}-${active}`}
          onKeyDown={onKeyDown}
          onPointerLeave={() => setShown(false)}
        >
          <span
            className="ui-wm-fill"
            aria-hidden="true"
            data-glide={fill.glide}
            style={{ transform: `translateY(${fill.y}px)`, height: fill.h, opacity: shown ? 1 : 0 }}
          />
          {OPTIONS.map((o, i) => (
            <div
              key={o.value}
              ref={(el) => {
                rows.current[i] = el;
              }}
              id={`${id}-${i}`}
              role="option"
              aria-selected={i === selected}
              className="ui-wm-option"
              onPointerEnter={() => {
                setActive(i);
                setShown(true);
              }}
              onClick={() => pick(i)}
            >
              <span className="ui-wm-option-name">{o.name}</span>
              <span className="ui-wm-check" aria-hidden="true">
                <TickIcon />
              </span>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

const ChevronIcon = () => (
  <svg className="ui-wm-chevron" viewBox="0 0 24 24" fill="none" aria-hidden="true">
    <path
      d="M18 9.00005C18 9.00005 13.5811 15 12 15C10.4188 15 6 9 6 9"
      className="ui-wm-chevron-ink"
      stroke="#737373"
      strokeWidth="1.5"
      strokeLinecap="round"
      strokeLinejoin="round"
    />
  </svg>
);

const TickIcon = () => (
  <svg
    viewBox="0 0 24 24"
    fill="none"
    stroke="currentColor"
    strokeWidth={1.75}
    strokeLinecap="round"
    strokeLinejoin="round"
    aria-hidden="true"
  >
    <path d="M5 14L8.5 17.5L19 6.5" />
  </svg>
);


/* ---------- Map data: Natural Earth 1:110m (public domain), Equal Earth projection, 540 × 242 viewBox ---------- */

/** Centre of each continent's main landmass, where the highlight scales in from */
const CENTER: Record<Continent, [number, number]> = {
  "north-america": [141, 49],
  "south-america": [181, 162],
  europe: [302, 36],
  africa: [296, 121],
  asia: [385, 56],
  oceania: [462, 185],
};

/**
 * Each continent merged into one shape without country borders, main landmass first
 * (Russia is split at the Urals, French Guiana belongs to South America)
 */
